import base64
import hashlib
import os
import secrets
import urllib.parse
from dataclasses import dataclass
from typing import Dict, Optional

import msal
import requests

AUTHORITY_TEMPLATE = "https://login.microsoftonline.com/{tenant_id}/v2.0"
DEFAULT_SCOPES = ["openid", "profile", "email", "offline_access"]


def _base64url_no_padding(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).rstrip(b"=").decode("ascii")


def generate_pkce_pair() -> Dict[str, str]:
    verifier = _base64url_no_padding(secrets.token_bytes(64))
    challenge = _base64url_no_padding(hashlib.sha256(verifier.encode("ascii")).digest())
    return {"code_verifier": verifier, "code_challenge": challenge}


@dataclass
class LoginFlowResult:
    authorization_url: str
    code_verifier: str
    token_response: Optional[Dict] = None
    userinfo: Optional[Dict] = None


class AzureEntraPKCEFlow:
    def __init__(
        self,
        client_id: Optional[str] = None,
        tenant_id: Optional[str] = None,
        redirect_uri: Optional[str] = None,
        scopes: Optional[list] = None,
    ):
        self.client_id = client_id or os.getenv("AZURE_CLIENT_ID")
        self.tenant_id = tenant_id or os.getenv("AZURE_TENANT_ID")
        self.redirect_uri = redirect_uri or os.getenv("AZURE_REDIRECT_URI", "http://localhost:8080/callback")
        self.scopes = scopes or DEFAULT_SCOPES

        if not self.client_id:
            raise ValueError("Missing AZURE_CLIENT_ID")
        if not self.tenant_id:
            raise ValueError("Missing AZURE_TENANT_ID")

        self.authority = AUTHORITY_TEMPLATE.format(tenant_id=self.tenant_id)
        self.app = msal.PublicClientApplication(client_id=self.client_id, authority=self.authority)

    def build_authorization_url(self, state: Optional[str] = None, nonce: Optional[str] = None) -> Dict[str, str]:
        pkce = generate_pkce_pair()
        auth_url = self.app.get_authorization_request_url(
            scopes=self.scopes,
            redirect_uri=self.redirect_uri,
            state=state or secrets.token_urlsafe(24),
            nonce=nonce or secrets.token_urlsafe(24),
            code_challenge=pkce["code_challenge"],
            code_challenge_method="S256",
        )
        return {
            "authorization_url": auth_url,
            "code_verifier": pkce["code_verifier"],
        }

    def exchange_code_for_token(self, authorization_code: str, code_verifier: str) -> Dict:
        result = self.app.acquire_token_by_authorization_code(
            code=authorization_code,
            scopes=self.scopes,
            redirect_uri=self.redirect_uri,
            code_verifier=code_verifier,
        )
        if "error" in result:
            raise RuntimeError(f"Token exchange failed: {result.get('error')} - {result.get('error_description')}")
        return result

    @staticmethod
    def fetch_userinfo(access_token: str) -> Dict:
        resp = requests.get(
            "https://graph.microsoft.com/oidc/userinfo",
            headers={"Authorization": f"Bearer {access_token}"},
            timeout=20,
        )
        resp.raise_for_status()
        return resp.json()

    def complete_login(self, authorization_code: str, code_verifier: str) -> LoginFlowResult:
        token = self.exchange_code_for_token(authorization_code, code_verifier)
        userinfo = None
        access_token = token.get("access_token")
        if access_token:
            userinfo = self.fetch_userinfo(access_token)
        return LoginFlowResult(
            authorization_url="",
            code_verifier=code_verifier,
            token_response=token,
            userinfo=userinfo,
        )


def create_login_start_url(state: Optional[str] = None, nonce: Optional[str] = None) -> Dict[str, str]:
    flow = AzureEntraPKCEFlow()
    return flow.build_authorization_url(state=state, nonce=nonce)


def handle_callback_and_fetch_profile(authorization_code: str, code_verifier: str) -> Dict:
    flow = AzureEntraPKCEFlow()
    result = flow.complete_login(authorization_code, code_verifier)
    return {
        "token_response": result.token_response,
        "userinfo": result.userinfo,
    }
